#[test]
fn max_message_bytes_limits_body_in_bytes() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    send(&mut h, "q", "abcd");
    send(&mut h, "q", "äö");
    for body in ["abcde", "äöx"] {
        let c = json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
        assert_eq!(h.err(c), "InvalidParameterValue", "{body}");
    }
    // The rule comes before the queue-type rules.
    let c = json!({"Command": "SendMessage", "QueueName": "q", "Body": "abcde", "GroupId": "g"});
    assert_eq!(h.err(c), "InvalidParameterValue");
    // A failed send does not use up a message id.
    assert_eq!(send(&mut h, "q", "x")["MessageId"], "m-3");
}

#[test]
fn max_message_bytes_attribute_rules() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5"), json!(5.5)] {
        let c = json!({"Command": "CreateQueue", "QueueName": "q",
                       "Attributes": {"MaxMessageBytes": bad}});
        assert_eq!(h.err(c), "InvalidParameterValue", "{bad}");
    }
    create(&mut h, "q", json!({"MaxMessageBytes": 10}));
    let get = |h: &mut Harness| {
        h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Attributes"]
            ["MaxMessageBytes"]
            .clone()
    };
    assert_eq!(get(&mut h), 10);
    // Takes part in CreateQueue rule 4.
    let same = json!({"Command": "CreateQueue", "QueueName": "q",
                      "Attributes": {"MaxMessageBytes": 10}});
    h.ok(same);
    let other = json!({"Command": "CreateQueue", "QueueName": "q"});
    assert_eq!(h.err(other), "QueueAlreadyExists");
}

#[test]
fn lowering_max_message_bytes_keeps_old_messages_and_dead_letters() {
    let mut h = Harness::new();
    create(&mut h, "dlq", json!({"MaxMessageBytes": 2}));
    create(&mut h, "q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1}));
    send(&mut h, "q", "long body");
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 1}}));
    assert_eq!(bodies(&receive(&mut h, "q", 1)), ["long body"]);
    h.tick(31);
    assert!(receive(&mut h, "q", 1).is_empty());
    assert_eq!(bodies(&receive(&mut h, "dlq", 1)), ["long body"]);
}
